// Stripe signature check: HMAC-SHA256 over `${timestamp}.${rawBody}`
// Needs env NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
const WEBHOOK_SECRET = 'whsec_REPLACE_ME';   // move to an env var or secret store in production
const TOLERANCE_SECONDS = 300;

const bad = (reason) => [{ json: { valid: false, reason } }];

const headers = $input.first().json.headers || {};
const sigHeader = headers['stripe-signature'];
if (!sigHeader) return bad('missing_signature_header');

let rawBody;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  rawBody = buf.toString('utf8');
} catch (e) {
  return bad('no_raw_body');
}

let t = null;
const v1 = [];
for (const part of sigHeader.split(',')) {
  const [k, v] = part.split('=');
  if (k === 't') t = v;
  if (k === 'v1') v1.push(v);
}
if (!t || v1.length === 0) return bad('malformed_signature_header');

const expected = crypto.createHmac('sha256', WEBHOOK_SECRET).update(`${t}.${rawBody}`, 'utf8').digest('hex');
const match = v1.some((sig) =>
  sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected)));
if (!match) return bad('signature_mismatch');

const age = Math.abs(Math.floor(Date.now() / 1000) - Number(t));
if (age > TOLERANCE_SECONDS) return bad('timestamp_outside_tolerance');

return [{ json: { valid: true, event: JSON.parse(rawBody) } }];

