const item = $input.first().json;
return [{ json: {
  event: item.event,
  config: {
    company_name: 'YOUR COMPANY LTD',
    company_address: '1 Example Street, London, UK',
    company_tax_id: 'GB000000000',
    from_email: 'billing@yourdomain.com',
    finance_email: 'finance@yourdomain.com',
    erp_base_url: 'https://erp.example.com/api',
    gotenberg_url: 'http://gotenberg:3000',
    s3_bucket: 'finance-receipts',
    stripe_api_version: '2025-03-31.basil',
    template_version: 'receipt-v1.0'
  }
} }];

const ZERO = ['bif','clp','djf','gnf','jpy','kmf','krw','mga','pyg','rwf','ugx','vnd','vuv','xaf','xof','xpf'];
const THREE = ['bhd','jod','kwd','omr','tnd'];
const major = (amt, cur) => {
  const c = String(cur || '').toLowerCase();
  const n = Number(amt || 0);
  return ZERO.includes(c) ? n : THREE.includes(c) ? n / 1000 : n / 100;
};
const taxOf = (o) => Array.isArray(o.total_taxes)
  ? o.total_taxes.reduce((s, t) => s + (t.amount || 0), 0)
  : (o.tax || 0);
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const isoDate = (unix) => new Date(unix * 1000).toISOString().slice(0, 10);

const inv = $json.event.data.object;
const cur = inv.currency;
const payload = {
  external_reference: inv.id,
  source: 'stripe',
  document_type: 'customer_invoice',
  invoice_number: inv.number,
  stripe_customer_id: inv.customer,
  erp_customer_id: inv.metadata?.erp_customer_id ?? null,
  customer_name: inv.customer_name,
  currency: String(cur).toUpperCase(),
  invoice_date: isoDate(inv.status_transitions?.finalized_at || inv.created),
  due_date: inv.due_date ? isoDate(inv.due_date) : null,
  subtotal: major(inv.total_excluding_tax ?? (inv.total - taxOf(inv)), cur),
  tax: major(taxOf(inv), cur),
  total: major(inv.total, cur),
  lines: (inv.lines?.data || []).map((l) => ({
    description: l.description, quantity: l.quantity ?? 1, amount: major(l.amount, cur)
  })),
  lines_truncated: !!inv.lines?.has_more,
  posting: { debit: 'ACCOUNTS_RECEIVABLE', credit: ['REVENUE_OR_DEFERRED', 'TAX_PAYABLE'] }
};
return [{ json: { idempotency_key: `stripe-invoice-finalized-${inv.id}`, erp_payload: payload } }];

