const ctx = $('Restore Context').first().json;
const ev = ctx.event.data.object;                 // what the webhook claimed
const inv = $('Get Invoice (Stripe)').first().json; // what Stripe says now
const pays = $input.first().json || {};
const cust = inv.customer && typeof inv.customer === 'object' ? inv.customer : {};
const cur = inv.currency;

const reasons = [];
if (inv.status !== 'paid') reasons.push(`Invoice status is "${inv.status}", expected "paid"`);
if (inv.id !== ev.id) reasons.push('Re-fetched invoice ID does not match the event');
if (inv.amount_paid !== ev.amount_paid) reasons.push(`Amount mismatch: event ${ev.amount_paid} vs API ${inv.amount_paid}`);
if (String(inv.currency).toLowerCase() !== String(ev.currency).toLowerCase()) reasons.push('Currency mismatch between event and API');
if (inv.amount_remaining !== 0) reasons.push(`Amount remaining is ${inv.amount_remaining}, expected 0`);
if (!(inv.amount_paid > 0)) reasons.push('Zero-value payment, no cash to post');
const email = cust.email || inv.customer_email || null;
if (!email) reasons.push('No billing email on customer or invoice');
const erpCustomerId = cust.metadata?.erp_customer_id || inv.metadata?.erp_customer_id || null;
if (!erpCustomerId) reasons.push('Missing erp_customer_id in Stripe metadata');
// TODO: add a lookup against your ERP/order record here and compare expected vs paid amount.

const pay = (pays.data || [])[0];
const pi = pay?.payment?.payment_intent && typeof pay.payment.payment_intent === 'object' ? pay.payment.payment_intent : null;
const charge = pi?.latest_charge && typeof pi.latest_charge === 'object' ? pi.latest_charge : null;
const pmd = charge?.payment_method_details || {};
const cc = String(cust.metadata?.billing_cc || '').split(',').map((s) => s.trim()).filter(Boolean);

return [{ json: {
  valid: reasons.length === 0,
  reasons,
  invoice_id: inv.id,
  invoice_number: inv.number,
  customer_name: cust.name || inv.customer_name,
  customer_email: email,
  cc,
  customer_tax_ids: (cust.tax_ids?.data || []).map((t) => `${t.type}: ${t.value}`),
  stripe_customer_id: typeof inv.customer === 'string' ? inv.customer : cust.id,
  erp_customer_id: erpCustomerId,
  currency: String(cur).toUpperCase(),
  amount_paid_minor: inv.amount_paid,
  amount_paid: major(inv.amount_paid, cur),
  subtotal: major(inv.total_excluding_tax ?? (inv.total - taxOf(inv)), cur),
  tax: major(taxOf(inv), cur),
  total: major(inv.total, cur),
  lines: (inv.lines?.data || []).map((l) => ({
    description: l.description, quantity: l.quantity ?? 1, amount: major(l.amount, cur)
  })),
  paid_at_iso: new Date((inv.status_transitions?.paid_at || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
  payment_method_type: pmd.type || null,
  card_brand: pmd.card?.brand || null,
  card_last4: pmd.card?.last4 || null,
  payment_intent_id: pi?.id || null,
  charge_id: charge?.id || null,
  balance_transaction_id: typeof charge?.balance_transaction === 'string' ? charge.balance_transaction : (charge?.balance_transaction?.id || null),
  hosted_invoice_url: inv.hosted_invoice_url
} }];

const v = $input.first().json;
const payload = {
  external_reference: `${v.invoice_id}:payment`,
  source: 'stripe',
  document_type: 'cash_receipt',
  posting_date: v.paid_at_iso.slice(0, 10),
  erp_customer_id: v.erp_customer_id,
  stripe_customer_id: v.stripe_customer_id,
  invoice_number: v.invoice_number,
  currency: v.currency,
  amount: v.amount_paid,
  posting: { debit: 'STRIPE_CLEARING', credit: 'ACCOUNTS_RECEIVABLE' },
  references: {
    stripe_invoice_id: v.invoice_id,
    payment_intent_id: v.payment_intent_id,
    charge_id: v.charge_id,
    balance_transaction_id: v.balance_transaction_id
  }
};
return [{ json: { idempotency_key: `stripe-invoice-paid-${v.invoice_id}`, erp_payload: payload } }];

