const crypto = require('crypto');
const item = $input.first();
const buf = await this.helpers.getBinaryDataBuffer(0, 'receipt');
const sha256 = crypto.createHash('sha256').update(buf).digest('hex');

const v = $('Validate Payment').first().json;
const b = $('Build Receipt').first().json;
const cfg = $('Config & Event').first().json.config;

const fileName = `${b.receipt_number}.pdf`;
const year = new Date(v.paid_at_iso).getUTCFullYear();
const s3Key = `receipts/${year}/${v.invoice_id}/${b.receipt_number}-${cfg.template_version}.pdf`;

item.binary.receipt.fileName = fileName;
item.binary.receipt.mimeType = 'application/pdf';
return [{ json: { sha256, size_bytes: buf.length, file_name: fileName, s3_key: s3Key }, binary: item.binary }];

// S3 node output does not reliably carry the file forward, so restore it from the hashing step.
const h = $('Hash PDF').first();
return [{ json: h.json, binary: h.binary }];

